actions.action:
// No nexus - no filing required
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

            // Calculate WV state additions
            double additions = 0.0;

            // WV requires addback of:
            // - Federal net operating loss (WV has separate NOL rules)
            // - Foreign taxes deducted federally
            // - State income taxes deducted on federal return
            // - Interest on obligations of other states (taxable to WV)
            // - Expenses related to exempt income

            // Example additions (would be calculated from entity fields):
            // additions += result.federal_nol_deduction;
            // additions += result.foreign_taxes_deducted;
            // additions += result.state_taxes_deducted;
            // additions += revenue.other_state_bond_interest;

            apportionment.state_additions = additions;

            // Calculate WV state subtractions
            double subtractions = 0.0;

            // WV allows subtraction of:
            // - Qualified Opportunity Zone business income
            // - Foreign source income (from sources outside U.S.)
            // - WV municipal bond interest (exempt for WV purposes)
            // - Certain dividend income adjustments

            // Example subtractions (would be calculated from entity fields):
            // subtractions += revenue.qoz_business_income;
            // subtractions += revenue.foreign_source_income;
            // subtractions += revenue.wv_municipal_interest;

            apportionment.state_subtractions = subtractions;

            // WV uses 6.5% flat rate
            apportionment.state_tax =
              apportionment.state_taxable_income * apportionment.state_tax_rate;

            // Subtract WV state credits
            // WV offers various credits: economic development, jobs creation,
            // research & development, historic preservation, etc.
            apportionment.state_tax =
              Math.max(0.0, apportionment.state_tax - apportionment.state_credits);

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;
